<?php

declare(strict_types=1);

namespace AtrioTeam\DigitalHub\Assets\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;
use Spatie\MediaLibrary\MediaCollections\Models\Media as SpatieMedia;

/**
 * Utilizzo di un asset dichiarato da un CMS/client (roadmap #34).
 *
 * Il consumer dichiara "questo mio contenuto linka questo vostro asset" alla
 * prima occorrenza; l'hub lo registra per poter **mostrare in UI dove un asset
 * risulta usato** prima di sostituirlo o revocarne il link pubblico.
 *
 * `source_type`/`source_id` sono opachi: identificano un'entità che vive in
 * un'altra applicazione, quindi non sono un morph e non hanno FK. `label` e
 * `source_url` servono solo a rendere leggibile e navigabile la riga in UI.
 *
 * Il registro è informativo, non vincolante: se i consumer "si dimenticano" di cancellare
 * il link, restano qui righe orfane che per l'hub risultano come utilizzate.
 * `last_seen_at`è l'unico dato che qui ci dice quando è stato usato l'ultima volta dal consumer,
 * quando il client fa un upsert.
 *
 * @property int $id
 * @property int $media_id
 * @property string $consumer
 * @property string $source_type
 * @property string $source_id
 * @property string $label
 * @property string|null $source_url
 * @property Carbon $last_seen_at
 */
class AssetUsage extends Model
{
    protected $guarded = [];

    protected $casts = [
        'last_seen_at' => 'datetime',
    ];

    /**
     * @return BelongsTo<SpatieMedia, $this>
     */
    public function media(): BelongsTo
    {
        /** @var class-string<SpatieMedia> $mediaModel */
        $mediaModel = config('media-library.media_model');

        return $this->belongsTo($mediaModel);
    }
}
